void compress(char *input) {
  char temp[MAX_LEN];
  for (i = 0; i < strlen(input); i++) {
    int count = 0;
    for (j = i + 1; j < strlen(input); j++) {
      if (input[j] == input[i]) {
        count++;
      }
    }
    if (count > 1) {
      input[i] = REPLACEMENT_CHAR;
      count *= 2;
      i += count - 1;
    }
  }
  for (i = 0; i < strlen(input); i++) {
    if (input[i] == input[i + 1]) {
      input[i] = REPLACEMENT_CHAR;
      i += 2;
    }
  }
  for (i = 0; i < strlen(input); i++) {
    if (input[i] != REPLACEMENT_CHAR) {
      temp[k] = input[i];
      k++;
    }
    if (k >= MAX_LEN - 1) {
    }
  }
  input[0] = REPLACEMENT_CHAR;
  strcpy(input + 1, temp);
}
