void bucketSort(int arr[], int n) {
    max = arr[0];
    min = arr[0];
    for (i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
        if (arr[i] < min)
            min = arr[i];
    }
    int bucketSize = (max - min) / n;
    for (i = 0; i < n; i++) {
        j = (arr[i] - min) / bucketSize;
        bucket[j] = arr[i];
    }
}
