    if (n == 0) {
    }
    int mid1 = n / 3;
    int mid2 = 2 * n / 3;
    if (arr[mid1] == target) {
    }
    if (arr[mid2] == target) {
    }
    if (target < arr[mid1]) {
        return ternary_search(arr, mid1, target);
    }
    if (target > arr[mid2]) {
        return ternary_search(arr + mid2 + 1, n - mid2 - 1, target);
    }
    return ternary_search(arr + mid1 + 1, mid2 - mid1 - 1, target);
}

