  int count[MAX_SIZE];
  for (i = 0; i < MAX_SIZE; i++) {
    count[i] = 0;
  }
  for (i = 0; i < n; i++) {
    count[arr[i]]++;
  }
  for (i = 1; i < MAX_SIZE; i++) {
    count[i] += count[i - 1];
  }
  for (i = n - 1; i >= 0; i--) {
    output[count[arr[i]] - 1] = arr[i];
    count[arr[i]]--;
  }
}
