int binaryToDecimal(char *binary) {
    int decimal = 0;
    int i = 0;
    while (binary[i] != '\0') {
        decimal = (decimal * 2) + (binary[i] - '0');
        i++;
    }
}
char *decimalToBinary(int decimal) {
    char *binary = malloc(sizeof(char) * (log10(decimal) + 1));
    int i = 0;
    while (decimal != 0) {
        binary[i] = (decimal % 2) + '0';
        decimal /= 2;
        i++;
    }
    binary[i] = '\0';
    return binary;
