void sort(int arr[], int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2;
        if (arr[mid] > arr[low]) {
            sort(arr, low, mid - 1);
            sort(arr, mid + 1, high);
        }
        if (arr[mid] < arr[low]) {
            sort(arr, low, mid - 1);
        }
    }
}
