int findMax(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}
int findMin(int arr[], int n) {
    int min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
}
int findMaxDiff(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minVal = findMin(arr, n - i);
        int maxVal = findMax(arr, n - i);
        int diff = maxVal - minVal;
    }
}
