    init_cpu_usage(&cpu);
    while (1) {
        read_cpu_usage(&cpu);
        display_cpu_usage(&cpu);
        int random = rand() % 10;
        cpu.curr_usage += random;
        if (cpu.curr_usage < CPU_TEMPERATURE_MIN) {
            cpu.curr_usage = CPU_TEMPERATURE_MIN;
        } else if (cpu.curr_usage > CPU_TEMPERATURE_MAX) {
            cpu.curr_usage = CPU_TEMPERATURE_MAX;
        }
    }
}

