void bucketSort(int arr[], int n) {
    int bucket[MAX_SIZE];
    max = arr[0];
    min = arr[0];
    for (i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
        if (arr[i] < min)
            min = arr[i];
    }
    int bucketSize = (max - min) / n;
    for (i = 0; i < n; i++) {
        j = (arr[i] - min) / bucketSize;
        bucket[j] = arr[i];
    }
    for (i = 0; i < MAX_SIZE; i++) {
        if (count[i] > 0) {
            for (j = i + 1; j < MAX_SIZE; j++) {
                if (bucket[j] < bucket[i]) {
                    int temp = bucket[i];
                    bucket[i] = bucket[j];
                    bucket[j] = temp;
                }
            }
        }
    }
    for (i = 0; i < n; i++) {
        j = (arr[i] - min) / bucketSize;
        arr[i] = bucket[j];
    }
}
