int factorial(int number) {
  int factorial = 1;
  for (int i = 1; i <= number; i++) {
    factorial *= i;
  }
  return factorial;
}
int binomial_coefficient(int n, int k) {
  return factorial(n) / (factorial(k) * factorial(n - k));
}
