void reverse_string(char *str) {
    for (i = 0; i < strlen(str); i++) {
        j = strlen(str) - i - 1;
        temp = str[i];
        str[i] = str[j];
        str[j] = temp;
    }
}
void rotate_string(char *str, int num_spaces) {
    for (i = 0; i < num_spaces; i++) {
        temp = str[i];
        for (j = i + 1; j < strlen(str); j++) {
            str[j - 1] = str[j];
        }
        str[j - 1] = temp;
    }
}
