int binarySearch(int arr[], int l, int r, int key){
    if(r >= l){
        int mid = l + (r-l)/2;
        else if(arr[mid] > key){
            return binarySearch(arr, l, mid-1, key);
        }
        else{
            return binarySearch(arr, mid+1, r, key);
        }
}
