void embedWatermark(byte *image, int width, int height, byte *watermark, int wWidth, int wHeight) {
    for (y = 0; y < height; y++) {
        for (x = 0; x < width; x++) {
            if (x < wWidth && y < wHeight) {
                int bit = (watermark[y * wWidth + x] & 1);
                int mask = 1 << (7 - (x % 8));
                image[y * width + x] = (image[y * width + x] & ~mask) | (bit << (7 - (x % 8)));
            }
        }
    }
}
