void bucketSort(int arr[], int n) {
  int count[MAX_SIZE];
  int output[MAX_SIZE];
  for (i = 0; i < MAX_SIZE; i++) {
    count[i] = 0;
  }
  for (i = 0; i < n; i++) {
    count[arr[i]]++;
  }
  for (i = 1; i < MAX_SIZE; i++) {
    count[i] += count[i - 1];
  }
  for (i = n - 1; i >= 0; i--) {
    output[count[arr[i]] - 1] = arr[i];
    count[arr[i]]--;
  }
}
int main() {
  int n = sizeof(arr) / sizeof(arr[0]);
  bucketSort(arr, n);
}

