void bucketSort(int arr[], int n) {
  int buckets[n];
  for (int i = 0; i < n; i++) {
    buckets[i] = 0;
  }
  for (int i = 0; i < n; i++) {
    int bucketIndex = arr[i] / n;
    buckets[bucketIndex]++;
  }
  for (int i = 0; i < n; i++) {
    int bucketIndex = arr[i] / n;
    int j = 0;
    while (j < buckets[bucketIndex]) {
      if (arr[i] < arr[j]) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
      j++;
    }
  }
}
