void bucketSort(float arr[], int n) {
  float max = arr[0];
  for (i = 1; i < n; i++) {
    if (arr[i] > max)
      max = arr[i];
  }
  max++;
  int bucket[n];
  for (i = 0; i < n; i++) {
  }
  for (i = 0; i < n; i++) {
    int bucketIndex = n * arr[i] / max;
    bucket[bucketIndex]++;
  }
  for (i = 0; i < n; i++) {
    int bucketIndex = n * arr[i] / max;
    float temp = arr[i];
    int tempCount = bucket[bucketIndex] - 1;
    for (j = bucketIndex - 1; j >= 0; j--) {
      if (bucket[j] != 0) {
        if (temp < j * max / n) {
          arr[i] = j * max / n;
          bucketIndex--;
          bucket[j]--;
        }
        tempCount += bucket[j];
      }
    }
    if (j < 0) {
      tempCount++;
      arr[i] = 0;
    }
    for (j = bucketIndex + 1; j < n; j++) {
      if (bucket[j] != 0) {
        if (temp > (j + 1) * max / n) {
          arr[tempCount++] = (j + 1) * max / n;
          bucket[j]--;
        } else {
      }
    }
    arr[tempCount] = temp;
    bucket[bucketIndex]--;
  }
}
