  long fileSize = ftell(file);
  rewind(file);
  char *buffer = malloc(fileSize + 1);
  fread(buffer, fileSize, 1, file);
  char *startOfData = buffer;
  while (*startOfData != '\n') {
    startOfData++;
  }
  startOfData++;
  char *data = malloc(strlen(startOfData) + 1);
