        remaining_time[i] = processes[i].burst_time;
    }
    while (1) {
        for (int i = 0; i < n; i++) {
            if (remaining_time[i] > 0) {
                done = 0;
                if (remaining_time[i] > quantum) {
                    time += quantum;
                    remaining_time[i] -= quantum;
                } else {
                    remaining_time[i] = 0;
                }
            }
        }
    }
}
